prompt:
Customers keep emailing that our booking request form 'does nothing' when they press the button. It does show errors, apparently, but people don't see them. Can you sort it out? Don't change how it looks apart from what's needed.

```html
<form id='req' novalidate>
  <h2>Request a table at Fennel &amp; Rye</h2>
  <label for='nm'>Name</label>
  <input id='nm' name='name'>
  <div class='err' id='e-nm'></div>
  <label for='pp'>Party size</label>
  <input id='pp' name='party' type='number' min='1' max='12'>
  <div class='err' id='e-pp'></div>
  <label for='dt'>Date</label>
  <input id='dt' name='date' type='date'>
  <div class='err' id='e-dt'></div>
  <button type='submit'>Send request</button>
  <div id='status'></div>
</form>
<style>
  .err { color: #d33; font-size: .85rem; min-height: 1rem; }
  input { border: 1px solid #aaa; padding: .4rem; }
  input.bad { border-color: #d33; }
</style>
<script>
  document.getElementById('req').addEventListener('submit', async (e) => {
    e.preventDefault();
    const f = e.target;
    let ok = true;
    if (!f.name.value) { e.target.querySelector('#e-nm').textContent = 'Required'; f.name.classList.add('bad'); ok = false; }
    if (!f.party.value) { document.getElementById('e-pp').textContent = 'Required'; f.party.classList.add('bad'); ok = false; }
    if (!f.date.value) { document.getElementById('e-dt').textContent = 'Required'; f.date.classList.add('bad'); ok = false; }
    if (!ok) return;
    await fetch('/request', { method: 'POST', body: new FormData(f) });
    document.getElementById('status').textContent = 'Sent';
  });
</script>
```
